// Each it() block is one test case: one scenario, one expected outcome
describe('PasswordReset', () => {
  it('sends a reset email when a valid address is submitted', async () => {
    const result = await requestPasswordReset('ada@example.com');
    expect(result.status).toBe('sent');
    expect(mockMailer.lastRecipient).toBe('ada@example.com');
  });

  it('returns not-found error for an unregistered email', async () => {
    const result = await requestPasswordReset('nobody@example.com');
    expect(result.status).toBe('not_found');
    expect(mockMailer.lastRecipient).toBeUndefined();
  });

  it('rejects a reset link that was used more than once', async () => {
    const token = await generateResetToken('ada@example.com');
    await consumeResetToken(token, 'newPass1');
    await expect(consumeResetToken(token, 'newPass2'))
      .rejects.toThrow('Token already used');
  });
});

// Jest expect() assertion library — various matcher types
import { describe, it, expect } from '@jest/globals';
import { getUser } from '../api/users';

describe('Assertion library examples', () => {
  it('checks primitive equality', () => {
    expect(2 + 2).toBe(4);                       // strict equality
    expect('hello world').toContain('world');    // substring
    expect([1, 2, 3]).toHaveLength(3);           // array length
  });

  it('checks object shape without requiring exact match', async () => {
    const user = await getUser(1);
    expect(user).toMatchObject({                 // partial object match
      id: 1,
      email: expect.stringContaining('@'),       // asymmetric matcher
      roles: expect.arrayContaining(['viewer']),
    });
  });

  it('verifies that an error is thrown', () => {
    expect(() => getUser(-1)).toThrow('Invalid user ID');
  });

  it('resolves async assertions', async () => {
    await expect(getUser(99)).rejects.toThrow('Not found');
  });
});
